CREATE OR REPLACE PACKAGE pivot_demo AS
  -- enum Region
  region_north CONSTANT VARCHAR2(200) := 'NORTH';
  region_south CONSTANT VARCHAR2(200) := 'SOUTH';
  region_east CONSTANT VARCHAR2(200) := 'EAST';
  region_west CONSTANT VARCHAR2(200) := 'WEST';
  TYPE t_regiontotals IS RECORD (
    product VARCHAR2(4000),
    north NUMBER,
    south NUMBER,
    east NUMBER,
    west NUMBER
  );
  TYPE t_RegionTotals_list IS TABLE OF t_regiontotals INDEX BY PLS_INTEGER;
  FUNCTION list_totals RETURN t_RegionTotals_list;
  FUNCTION region_sales_dyn RETURN SYS_REFCURSOR;
END pivot_demo;
